        String urlString = reader.readLine();

        // BAD CODE: Directly constructing a URL from untrusted input without validation.
        // This creates a vulnerable Server-Side Request Forgery (SSRF) vulnerability.
        // An attacker can provide "file:///etc/passwd" or an internal IP address 
        // to access sensitive data or internal services that are not exposed to the public internet.
        URL url = new URL(urlString); 

        // Attempting to connect to the URL directly allows arbitrary network requests.
