import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.net.UnknownHostException;

public class FixedWebApp {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String urlString = reader.readLine();

        // Validate the input to ensure it is a valid HTTP/HTTPS URL
        if (!isValidUrl(urlString)) {
            System.out.println("Invalid URL format.");
            return;
        }

        URL url = new URL(urlString);

        // Check if the resolved host is a private or loopback address to prevent SSRF.
        // This prevents accessing internal networks (192.168.x.x, 10.x.x.x, 127.x.x.x).
        InetAddress ip = InetAddress.getByName(url.getHost());

        if (ip.isAnyLocalAddress() || ip.isLoopbackAddress() || ip.isSiteLocalAddress()) {
            System.out.println("Access denied: Cannot access internal/private addresses.");
            return;
        }

        // Now safe to open the connection
        if (url.openStream() != null) {
            System.out.println("Successfully fetched content.");
        }
    }

    // Helper method to validate URL protocol and format
    private static boolean isValidUrl(String urlString) {
        try {
            URL url = new URL(urlString);
            return "http".equalsIgnoreCase(url.getProtocol()) || 
                   "https".equalsIgnoreCase(url.getProtocol());
        } catch (Exception e) {
            return false;
        }
    }
}
